// A copy of the Vortex design system's components/lib/vortex-mark-geometry.js. Edit the system, then copy it again.

// Generated from the Vortex mark model by tools/glb-to-geometry.mjs. Do not edit.
export const positions = "";
export const normals = "";
export const indices = "";
const bytes = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0)).buffer;
/** The mark's geometry as typed arrays. */
export function decode() {
  return { positions: new Float32Array(bytes(positions)), normals: normals ? new Float32Array(bytes(normals)) : null, indices: new Uint16Array(bytes(indices)) };
}
